 p=g[lo:hi]
 print('panel',lo,hi,'color runs')
 for c in (2,4):
  runs=[]
  for j in range(9):
   vals=[i for i,row in enumerate(p) if row[j]==c]
   if vals:runs.append((j,min(vals),max(vals),len(vals)))
